def crack_single_byte_xor(ciphertext: bytes):
    best_score, best_key = -1, 0
    for key in range(256):
        plain = bytes(b ^ key for b in ciphertext)
        score = sum(1 for b in plain if 32 <= b < 127)
        if score > best_score:
            best_score, best_key = score, key
    return best_key

